keyToHistory = Object.create(null);

//###########################################################
createSampleDataArray = function(length) {
  var delta, deltaRange, idx, result, val;
  result = new Array(length);
  idx = 0;
  deltaRange = 4;
  val = 100;
  while (idx < length) {
    result[idx] = val;
    delta = (Math.random() - 0.5) * deltaRange;
    val += delta;
    idx++;
  }
  return result;
};

//###########################################################
createSampleData = function(key, toAge = 30) {
  var cnt, currentYear, currentYearDays, historicDailyCloses, today, year, yearDays, yearStart;
  today = new Date();
  yearStart = getJan1Date();
  currentYearDays = dateDifDays(yearStart, today);
  log("currentYearDays: " + currentYearDays);
  currentYear = today.getFullYear();
  historicDailyCloses = new Array(toAge + 1);
  historicDailyCloses[0] = createSampleDataArray(currentYearDays);
  cnt = 1;
  while (cnt < historicDailyCloses.length) {
    year = currentYear - cnt;
    yearDays = getDaysOfYear(year);
    historicDailyCloses[cnt] = createSampleDataArray(yearDays);
    cnt++;
  }
  keyToHistory[key] = historicDailyCloses;
};

getLatestSampleData = function(history, toAge) {
  var age, result, runLimit;
  result = [];
  age = 0;
  runLimit = toAge + 1;
  while (age < runLimit) {
    if (history[age] == null) {
      break;
    }
    result.push(history[age]);
    age++;
  }
  return result;
};

//###########################################################
export var getMarketHistory = function(key, toAge) {
  if (!keyToHistory[key]) {
    createSampleData(key);
  }
  return getLatestSampleData(keyToHistory[key], toAge);
};

