testYearCalculation = function() {
  var days, expectedDays, i, len, results, test, tests, year;
  tests = [[1600, 366], [1601, 365], [1604, 366], [1700, 365], [1800, 365], [1900, 365], [2000, 366], [2100, 365], [2102, 365], [2103, 365], [2104, 366]];
  results = [];
  for (i = 0, len = tests.length; i < len; i++) {
    test = tests[i];
    year = test[0];
    expectedDays = test[1];
    days = getDaysOfYear(year);
    if (days !== expectedDays) {
      results.push(log(`Error @year ${year}: had ${days}days and not ${expectedDays}!`));
    } else {
      results.push(log(`Success @year ${year}!`));
    }
  }
  return results;
};
